#!/usr/bin/env node
// Turns lib/projects/scaffold/template/ (real, editable files) into
// lib/projects/scaffold/files.generated.ts — a plain module, so the scaffold ships inside
// every bundle that creates projects (Next server, SOL's Lambda) with no file-system reads.
// Run after editing the template: node scripts/build-project-scaffold.mjs
// (tests/projectScaffold.test.ts fails if the generated file is out of date.)
import { readFileSync, writeFileSync, readdirSync, statSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const templateDir = join(root, "lib/projects/scaffold/template");
const outFile = join(root, "lib/projects/scaffold/files.generated.ts");

export function collectScaffold() {
  const files = {};
  const walk = (dir) => {
    for (const name of readdirSync(dir).sort()) {
      const full = join(dir, name);
      if (statSync(full).isDirectory()) walk(full);
      else files[relative(templateDir, full).split(sep).join("/")] = readFileSync(full, "utf8");
    }
  };
  walk(templateDir);
  return files;
}

export function renderScaffoldModule(files) {
  return (
    "// GENERATED by scripts/build-project-scaffold.mjs from lib/projects/scaffold/template/ — do not edit.\n" +
    "export const SCAFFOLD_FILES: Record<string, string> = " +
    JSON.stringify(files, null, 2) +
    ";\n"
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const files = collectScaffold();
  writeFileSync(outFile, renderScaffoldModule(files));
  console.log(`Wrote ${Object.keys(files).length} scaffold files to ${relative(root, outFile)}`);
}
